    fputs("\n PEAK AND GAIN\n  Peak is measured after the selected DC correction. New Peak predicts\n  the scaled peak BEFORE limiting, dithering and output quantization.\n  Manual gain is added once, then capped unless --noclip is used.\n  --limiter does not remove this cap; combine with --noclip to bypass it.\n\n", stdout);
